parameters.jsCode:
// Keeps only links that point at a page Tavily actually returned for this section,
// and strips any HTML that isn't safe for an email body
const section = $('Split into sections').item.json;
const results = $('Research the section').item.json.results || [];
const out = $json.output || {};

const key = url => String(url || '').trim().replace(/#.*$/, '').replace(/\/+$/, '').toLowerCase();
const found = new Map(results.map(r => [key(r.url), r]));

const used = new Map();
let removed = 0;
let html = String(out.html || '')
  .replace(/<(script|style|iframe|object|embed|form)[\s\S]*?<\/\1>/gi, '')
  .replace(/<a\b[^>]*?href\s*=\s*["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi, (match, url, text) => {
    const hit = found.get(key(url));
    if (!hit) {
      removed += 1;
      return text;
    }
    used.set(hit.url, hit.title || hit.url);
    return `<a href="${hit.url}">${text}</a>`;
  });

const ALLOWED = ['p', 'ul', 'ol', 'li', 'strong', 'em', 'b', 'i', 'br', 'a'];
html = html.replace(/<(\/?)([a-z0-9]+)\b[^>]*>/gi, (tag, slash, name) => {
  name = name.toLowerCase();
  if (!ALLOWED.includes(name)) return '';
  return name === 'a' ? tag : `<${slash}${name}>`;
});

return {
  json: {
    index: section.index,
    heading: String(out.heading || section.title).trim(),
    html: html.trim(),
    takeaway: String(out.takeaway || '').trim(),
    sources: [...used].map(([url, title]) => ({ url, title })),
    links_removed: removed,
    results_found: results.length,
  },
};

// Puts the checked sections back in order and builds one numbered source list
const sections = $input.all().map(i => i.json).sort((a, b) => a.index - b.index);

const sources = [];
const seen = new Set();
for (const s of sections) {
  for (const src of s.sources) {
    if (!seen.has(src.url)) {
      seen.add(src.url);
      sources.push(src);
    }
  }
}

return [{
  json: {
    sections,
    sources,
    section_summary: sections.map(s => `- ${s.heading}: ${s.takeaway}`).join('\n'),
    links_removed: sections.reduce((n, s) => n + s.links_removed, 0),
    sections_without_sources: sections.filter(s => !s.sources.length).map(s => s.heading),
  },
}];

parameters.text:
=Write the subject line, preview text and a short intro for this newsletter issue.

Topic: {{ $('Read the brief').first().json.topic }}
Audience: {{ $('Read the brief').first().json.audience }}
Tone: {{ $('Read the brief').first().json.tone }}
Angle: {{ $('Split into sections').first().json.newsletter_angle }}

Sections and their takeaways:
{{ $json.section_summary }}

