parameters.jsCode:
// Wraps the intro, sections and sources in a simple email layout with inline styles
const brief = $('Read the brief').first().json;
const body = $('Combine the sections').first().json;
const top = $json.output || {};

const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const font = 'font-family:Georgia,serif;color:#1f2933;line-height:1.6;';

const sectionsHtml = body.sections.map(s => `
  <h2 style="font-family:Arial,sans-serif;font-size:20px;margin:28px 0 8px;">${esc(s.heading)}</h2>
  ${s.html}`).join('\n');

const sourcesHtml = body.sources.length
  ? `<h3 style="font-family:Arial,sans-serif;font-size:16px;margin:32px 0 8px;">Sources</h3>
  <ol style="font-size:14px;">${body.sources.map(s => `<li><a href="${s.url}">${esc(s.title)}</a></li>`).join('')}</ol>`
  : '';

const html = `<div style="max-width:640px;margin:0 auto;padding:24px;${font}">
  <span style="display:none;">${esc(top.preheader)}</span>
  <h1 style="font-family:Arial,sans-serif;font-size:26px;margin:0 0 4px;">${esc(top.subject)}</h1>
  <p style="font-size:13px;color:#52606d;margin:0 0 20px;">For ${esc(brief.audience)} · ${esc(brief.issue_date)}</p>
  ${top.intro_html || ''}
  ${sectionsHtml}
  ${sourcesHtml}
  <p style="font-size:12px;color:#7b8794;margin-top:32px;">Every link above was checked against the search results used to write it.</p>
</div>`;

return [{
  json: {
    subject: String(top.subject || brief.topic).slice(0, 120),
    html,
    send_to: brief.send_to,
    sender_name: brief.sender_name,
    delivery_mode: brief.delivery_mode,
    section_count: body.sections.length,
    source_count: body.sources.length,
    links_removed: body.links_removed,
    sections_without_sources: body.sections_without_sources,
  },
}];
